import { fetchAppEmbeddedKey } from './fetchAppEmbeddedKey';
export const fetchViaFrame = async (url, options = {}) => {
    const apiKey = await fetchAppEmbeddedKey();
    const init = {
        ...options,
        headers: {
            ...options.headers,
            Authorization: `Bearer ${apiKey}`,
        },
    };
    const response = await fetch(url, init);
    const headers = {};
    response.headers.forEach((value, key) => {
        headers[key] = value;
    });
    const serializableResponse = {
        json: undefined,
        arrayBuffer: undefined,
        headers,
        ok: response.ok,
        redirected: response.redirected,
        status: response.status,
        statusText: response.statusText,
        type: response.type,
        url: response.url,
    };
    switch (response.headers.get('Content-Type')) {
        case 'application/json':
            serializableResponse.json = await response.json();
            break;
        default:
            serializableResponse.arrayBuffer = await response.arrayBuffer();
            break;
    }
    return serializableResponse;
};
